    def test_empty_and_inverted_intervals_ignored(self):
        self.assertEqual(solution.merge([(3, 3), (5, 4), (1, 2)]), [(1, 2)])

    def test_nested(self):
        self.assertEqual(solution.merge([(1, 10), (2, 3), (4, 5)]), [(1, 10)])

